import{samples,audit,generate,questions}from'./core.js';
const $=id=>document.getElementById(id);let selected='lamp',result,product,uploaded='';const fields=['name','material','size','facts','copy'];
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function status(t){$('status').textContent=t;}
function read(){return Object.fromEntries(fields.map(k=>[k,$(k).value.trim()]));}
function report(items){return items.length?items.map(x=>`<article class="risk"><strong>${esc(x.label)}</strong><p>${esc(x.detail)}</p></article>`).join(''):'<article class="risk safe"><strong>未命中当前规则</strong><p>仍需人工核对语义、商品事实和交易条件；不代表完整审核通过。</p></article>';}
function render(){product=read();result=generate(product,$('lang').value,$('tone').value);$('result-type').textContent=result.type;$('result-title').textContent=result.title;$('result-body').textContent=result.body;$('result-bullets').replaceChildren(...result.bullets.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('back-translation').textContent=result.back;$('original-copy').textContent=product.copy;$('product-image').src=uploaded||`assets/${result.asset}.svg`;$('product-image').alt=uploaded?'用户上传的商品图片':`${product.name}示意插画`;$('language-badge').textContent=$('lang').value==='en'?'ENGLISH EDIT':'JAPANESE EDIT';const risks=audit(product.copy,product,{source:true});$('risk-count').textContent=risks.length;$('risk-list').innerHTML=report(risks);$('reasons').innerHTML=`<details open><summary>保留材质、规格与已确认特点</summary><p>依据：${esc(product.material)}；${esc(product.size)}；${esc(product.facts)}。生成卡片沿用这些字段，不引入价格与物流承诺。</p></details><details><summary>将夸张表达替换成具体使用场景</summary><p>不沿用未经支持的治疗、排名或认证表述。场景文案是创作表达，不是用户调查结论。</p></details><details><summary>语言与风格说明</summary><p>${result.type==='策划示例'?'当前使用预先策划的双语案例；风格切换修改标题表达。':'当前为自定义商品的规则草稿，保留原文以避免虚构翻译。'} 中文释义供理解，发布前应复核外语表达。</p></details>`;$('questions').replaceChildren(...questions(product).map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('candidate').value=[result.title,result.body,...result.bullets].join('\n');$('candidate-report').innerHTML='';try{localStorage.setItem('chuhai-draft',JSON.stringify({product,lang:$('lang').value,tone:$('tone').value,selected}));}catch{} }
function sample(id){selected=id;uploaded='';$('photo').value='';fields.forEach(k=>$(k).value=samples[id][k]);document.querySelectorAll('[data-sample]').forEach(b=>b.classList.toggle('active',b.dataset.sample===id));render();}
function tab(id){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===id?'true':'false'));['preview','analysis','lock'].forEach(k=>$(k).hidden=k!==id);}
document.querySelectorAll('[data-sample]').forEach(b=>b.addEventListener('click',()=>{sample(b.dataset.sample);status('已载入案例。');}));document.querySelectorAll('[data-tab]').forEach(b=>{b.addEventListener('click',()=>tab(b.dataset.tab));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const keys=['preview','analysis','lock'];let i=keys.indexOf(b.dataset.tab);const k=keys[(i+(e.key==='ArrowRight'?1:2))%3];tab(k);$('tab-'+k).focus();});});
$('product-form').addEventListener('submit',e=>{e.preventDefault();if(fields.some(k=>!$(k).value.trim())){status('请补全商品事实与原始文案。');return;}render();tab('preview');status(`已完成试穿：${result.type}。可切换“文案对照”和“事实锁”查看依据。`);});['lang','tone'].forEach(id=>$(id).addEventListener('change',()=>{render();status('已切换表达。');}));fields.forEach(k=>$(k).addEventListener('input',()=>{status('商品内容已修改，请点击“开始试穿”更新结果。');document.querySelectorAll('[data-sample]').forEach(b=>b.classList.remove('active'));}));
$('check').onclick=()=>{if(!fields.every(k=>read()[k]===product[k])){status('事实已修改，请先点击“开始试穿”保存新事实，再检查文案。');return;}if(!$('candidate').value.trim()){$('candidate-report').textContent='请先输入待检查文案。';return;}$('candidate-report').innerHTML=report(audit($('candidate').value,product));};$('inject').onclick=()=>{$('candidate').value='Certified eco-friendly. Free shipping worldwide. Height: 99 cm. Cures insomnia.';$('check').click();};
$('photo').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){e.target.value='';status('请选择不超过 5 MB 的 PNG、JPG 或 WebP 图片。');return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{if(img.width*img.height>30000000){status('图片分辨率过大，请压缩后重试。');return;}uploaded=reader.result;$('product-image').src=uploaded;status('图片已在本地载入，不会上传到服务器。');};img.onerror=()=>status('无法读取该图片，请选择有效图片。');img.src=reader.result;};reader.readAsDataURL(f);};
function download(data,name,type){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
$('export-text').onclick=()=>{download(`# ${product.name}\n\n模式：${result.type}\n语言：${$('lang').value}\n\n## 商品事实\n${product.material}\n${product.size}\n${product.facts}\n\n## 试穿文案\n${result.title}\n${result.body}\n${result.bullets.join('\n')}\n\n## 中文说明\n${result.back}\n\n## 原文规则检查\n${audit(product.copy,product,{source:true}).map(x=>x.label+'：'+x.detail).join('\n')||'未命中当前规则，仍需人工审核。'}\n\n## 检查限制\n规则覆盖有限，不构成语义或合规审核。\n`,'出海试衣间-文案与报告.md','text/markdown;charset=utf-8');status('文案与报告已导出。');};
$('export-png').onclick=async()=>{try{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const c=canvas.getContext('2d');c.fillStyle='#f4f2e9';c.fillRect(0,0,1080,1350);c.fillStyle='#e8e5d9';c.fillRect(0,0,1080,600);const img=new Image();img.src=$('product-image').src;await img.decode();const scale=Math.min(960/img.width,520/img.height);c.drawImage(img,(1080-img.width*scale)/2,40+(520-img.height*scale)/2,img.width*scale,img.height*scale);c.fillStyle='#173e35';c.font='20px monospace';c.fillText('CHUHAI STUDIO / THE LOCAL EDIT',65,58);let y=690;const wrap=(text,size,line)=>{c.font=`${size}px "Microsoft YaHei", Georgia`;let row='';for(const ch of text){if(c.measureText(row+ch).width>940){c.fillText(row,65,y);y+=line;row='';}row+=ch;}if(row){c.fillText(row,65,y);y+=line;}};wrap(result.title,44,58);y+=16;wrap(result.body,26,42);y+=15;result.bullets.forEach(t=>wrap('• '+t,24,39));c.font='18px "Microsoft YaHei"';c.fillText('出海试衣间 · '+result.type+' · 发布前请复核',65,1300);canvas.toBlob(b=>{if(!b){status('导出失败，请重试。');return;}download(b,'出海试衣间-商品卡片.png');status('商品卡片已导出。');},'image/png');}catch{status('图片导出失败，请更换图片后重试。');}};
$('theme').onclick=()=>document.body.classList.toggle('dark');
sample('lamp');try{const saved=JSON.parse(localStorage.getItem('chuhai-draft-backup')||'null');if(saved&&samples[saved.selected]){selected=saved.selected;fields.forEach(k=>$(k).value=String(saved.product[k]||''));$('lang').value=['en','ja'].includes(saved.lang)?saved.lang:'en';$('tone').value=['warm','clean','gift'].includes(saved.tone)?saved.tone:'warm';render();}}catch{}window.addEventListener('beforeunload',()=>{try{localStorage.setItem('chuhai-draft-backup',JSON.stringify({product:read(),lang:$('lang').value,tone:$('tone').value,selected}));}catch{}});
